 using Contoso.Text;
 using Microsoft.VisualStudio.TestTools.UnitTesting;

 namespace Contoso.Text.Tests;

 [TestClass]
 public sealed class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     // --- FormatPhoneNumber ---

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber()
     {
         var result = _formatter.FormatPhoneNumber("1234567890");

         Assert.AreEqual("(123) 456-7890", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCode()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.StartsWith("(555)", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.EndsWith("4567", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_MatchesPhonePattern()
     {
         var result = _formatter.FormatPhoneNumber("8005551234");

         Assert.MatchesRegex(@"^\(\d{3}\) \d{3}-\d{4}$", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_Null_ThrowsArgumentNullException()
     {
         var ex = Assert.ThrowsExactly<ArgumentNullException>(
             () => _formatter.FormatPhoneNumber(null!));

         Assert.AreEqual("digits", ex.ParamName);
     }

     [TestMethod]
     [DataRow("123", DisplayName = "Too short")]
     [DataRow("12345678901", DisplayName = "Too long")]
     [DataRow("", DisplayName = "Empty")]
     public void FormatPhoneNumber_InvalidLength_ThrowsArgumentException(string digits)
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.FormatPhoneNumber(digits));
     }

     // --- BuildGreeting ---

     [TestMethod]
     public void BuildGreeting_DefaultTitle_ReturnsDearMrGreeting()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.AreEqual("Dear Mr. Smith,", result);
     }

     [TestMethod]
     public void BuildGreeting_CustomTitle_StartsWithDearAndTitle()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.StartsWith("Dear Dr.", result);
     }

     [TestMethod]
     public void BuildGreeting_AnyInput_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Doe", "Ms.");

         Assert.EndsWith(",", result);
     }

     [TestMethod]
     public void BuildGreeting_AnyInput_ContainsName()
     {
         var result = _formatter.BuildGreeting("Anderson", "Prof.");

         Assert.Contains("Anderson", result);
     }

     [TestMethod]
     public void BuildGreeting_NullName_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(
             () => _formatter.BuildGreeting(null!));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void BuildGreeting_WhitespaceName_ThrowsArgumentException(string name)
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.BuildGreeting(name));
     }

     // --- GenerateSlug ---

     [TestMethod]
     public void GenerateSlug_SimpleTitle_ReturnsLowercaseHyphenated()
     {
         var result = _formatter.GenerateSlug("Hello World");

         Assert.AreEqual("hello-world", result);
     }

     [TestMethod]
     [DataRow("My Blog Post", "my-blog-post")]
     [DataRow("  Trimmed Spaces  ", "trimmed-spaces")]
     [DataRow("Special!@#Characters", "special-characters")]
     [DataRow("Multiple   Spaces", "multiple-spaces")]
     public void GenerateSlug_VariousTitles_ReturnsExpectedSlug(string title, string expected)
     {
         var result = _formatter.GenerateSlug(title);

         Assert.AreEqual(expected, result);
     }

     [TestMethod]
     public void GenerateSlug_Result_MatchesSlugPattern()
     {
         var result = _formatter.GenerateSlug("Test Title 123!");

         Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
     }

     [TestMethod]
     public void GenerateSlug_NullTitle_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(
             () => _formatter.GenerateSlug(null!));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void GenerateSlug_WhitespaceTitle_ThrowsArgumentException(string title)
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.GenerateSlug(title));
     }

     // --- FormatCurrency ---

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
     {
         var result = _formatter.FormatCurrency(19.99m);

         Assert.StartsWith("$", result);
     }

     [TestMethod]
     public void FormatCurrency_EuroSymbol_StartsWithEuro()
     {
         var result = _formatter.FormatCurrency(42.50m, "€");

         Assert.StartsWith("€", result);
     }

     [TestMethod]
     public void FormatCurrency_WholeNumber_EndsWithTwoDecimalPlaces()
     {
         var result = _formatter.FormatCurrency(100m);

         Assert.EndsWith(".00", result);
     }

     [TestMethod]
     [DataRow(19.99, "$", "$19.99")]
     [DataRow(0.0, "€", "€0.00")]
     [DataRow(-5.5, "$", "$-5.50")]
     [DataRow(1234.567, "£", "£1234.57")]
     public void FormatCurrency_VariousAmounts_ReturnsExpected(
         double amount, string symbol, string expected)
     {
         var result = _formatter.FormatCurrency((decimal)amount, symbol);

         Assert.AreEqual(expected, result);
     }
 }
